// pgr4-native PGR4 native renderer: FidelityFX Frame Generation. See frame_generation.h.
#include "frame_generation.h"

#include "log.h"

#include <dx12/ffx_api_dx12.h>
#include <ffx_framegeneration.h>

#include <rex/cvar.h>
#include <rex/graphics/registers.h>
#include <rex/graphics/xenos.h>
#include <rex/logging.h>

REXCVAR_DEFINE_BOOL(pgr4_native_frame_generation, false, "PGR4 native",
                    "Present a frame generated by AMD FidelityFX Frame Generation "
                    "(amd_fidelityfx_framegeneration_dx12.dll beside the executable, or what "
                    "OptiScaler puts behind it) before each frame, from the upscaler's depth and "
                    "motion, at half the display's refresh rate: with --pgr4_native_upscaler "
                    "(bind_upscaler, F7) and the frame pacer (--pgr4_native_primary)");

namespace pgr4::native {

namespace {

namespace xenos = rex::graphics::xenos;

// A color target's EDRAM data: its base and storage format, which a format's _AS_16_16_16_16
// variant shares (PGR4 composites the front buffer in 2_10_10_10_FLOAT and draws the HUD over it
// in 2_10_10_10_FLOAT_AS_16_16_16_16, td-265).
uint32_t ColorStorage(uint32_t color_info) {
  const auto format = xenos::ColorRenderTargetFormat((color_info >> 16) & 0xF);
  return (color_info & 0xFFF) | uint32_t(xenos::GetStorageColorFormat(format)) << 16;
}

}  // namespace

bool FrameGeneration::Requested() { return REXCVAR_GET(pgr4_native_frame_generation); }

FrameGeneration::~FrameGeneration() { Destroy(); }

bool FrameGeneration::Initialize() {
  api_ = LoadFfxApi();
  if (!api_) return false;
  D3D12_DESCRIPTOR_HEAP_DESC hd = {};
  hd.Type = D3D12_DESCRIPTOR_HEAP_TYPE_RTV;
  hd.NumDescriptors = 2;
  rtv_stride_ = device_.device()->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_RTV);
  return !Failed(device_.device()->CreateDescriptorHeap(&hd, IID_PPV_ARGS(&rtv_heap_)),
                 "CreateDescriptorHeap(frame generation RTVs)");
}

D3D12_CPU_DESCRIPTOR_HANDLE FrameGeneration::Rtv(uint32_t i) const {
  D3D12_CPU_DESCRIPTOR_HANDLE h = rtv_heap_->GetCPUDescriptorHandleForHeapStart();
  h.ptr += size_t(i) * rtv_stride_;
  return h;
}

void FrameGeneration::OnSwap(uint32_t front_base) {
  if (last_resolve_.source < 4 && last_resolve_.dest_base == front_base)
    front_ = last_resolve_;
  else
    front_.reset();
}

bool FrameGeneration::CopyAtHud(CommandStream* list, uint64_t frame, const uint32_t* regs) {
  using enum rex::graphics::Register;
  const SurfaceRegs& f = front_->regs;
  // RT 0 of the draw is the front buffer's surface (pitch, MSAA, EDRAM data), written.
  if (regs[XE_GPU_REG_RB_SURFACE_INFO] != f.surface_info ||
      ColorStorage(regs[XE_GPU_REG_RB_COLOR_INFO]) != ColorStorage(f.color_info[front_->source]) ||
      !(regs[XE_GPU_REG_RB_COLOR_MASK] & 0x7))
    return false;
  // RB_BLENDCONTROL0's color part: source ONE, ADD, destination ZERO replaces what was there.
  if ((regs[XE_GPU_REG_RB_BLENDCONTROL0] & 0x1FFF) == 0x0001) {
    composited_frame_ = frame;
    return false;
  }
  if (composited_frame_ != frame) return false;
  copy_frame_ = frame;
  copy_ = resolver_.ResolveCopy(list, *front_);
  return true;
}

void FrameGeneration::Destroy() {
  if (context_) api_->destroy(&context_, nullptr);
  context_ = nullptr;
  image_.Reset();
  hudless_.Reset();
  output_.Reset();
  width_ = height_ = 0;
}

bool FrameGeneration::Resize(uint32_t width, uint32_t height, bool hdr, bool debug) {
  if (context_ && width == width_ && height == height_ && hdr == hdr_ && debug == debug_)
    return true;
  device_.WaitIdle();
  Destroy();
  const DXGI_FORMAT format =
      hdr ? D3D12Device::kHdrBackBufferFormat : D3D12Device::kBackBufferFormat;
  ID3D12Device* device = device_.device();
  const D3D12_HEAP_PROPERTIES heap = {D3D12_HEAP_TYPE_DEFAULT};
  D3D12_RESOURCE_DESC rd = {
      D3D12_RESOURCE_DIMENSION_TEXTURE2D, 0, width, height, 1, 1, format, {1, 0}};
  rd.Flags = D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET;
  if (Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&image_)),
             "CreateCommittedResource(frame generation image)") ||
      Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&hudless_)),
             "CreateCommittedResource(frame generation HUD-less image)"))
    return false;
  rd.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
  if (Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&output_)),
             "CreateCommittedResource(generated frame)"))
    return false;
  device->CreateRenderTargetView(image_.Get(), nullptr, image_rtv());
  device->CreateRenderTargetView(hudless_.Get(), nullptr, hudless_rtv());

  ffxCreateBackendDX12Desc backend = {};
  backend.header.type = FFX_API_CREATE_CONTEXT_DESC_TYPE_BACKEND_DX12;
  backend.device = device;
  ffxCreateContextDescFrameGenerationVersion version = {};
  version.header.type = FFX_API_CREATE_CONTEXT_DESC_TYPE_FRAMEGENERATION_VERSION;
  version.header.pNext = &backend.header;
  version.version = FFX_FRAMEGENERATION_VERSION;
  ffxCreateContextDescFrameGeneration cd = {};
  cd.header.type = FFX_API_CREATE_CONTEXT_DESC_TYPE_FRAMEGENERATION;
  cd.header.pNext = &version.header;
  // The scene's depth is reversed (cleared to 0, tested GEQUAL); with HDR the image is PQ.
  cd.flags = FFX_FRAMEGENERATION_ENABLE_DEPTH_INVERTED |
             (hdr ? FFX_FRAMEGENERATION_ENABLE_HIGH_DYNAMIC_RANGE : 0u);
  cd.displaySize = {width, height};
  cd.maxRenderSize = {kFfxSceneWidth, FrameHeight()};
  cd.backBufferFormat = ffxApiGetSurfaceFormatDX12(format);
  SetFfxWatermark(L"MLFI-WATERMARK", debug);
  if (const ffxReturnCode_t rc = api_->create(&context_, &cd.header, nullptr);
      rc != FFX_API_RETURN_OK) {
    REXLOG_ERROR("PGR4 native frame generation: ffxCreateContext failed ({})", rc);
    context_ = nullptr;
    return false;
  }
  width_ = width;
  height_ = height;
  hdr_ = hdr;
  debug_ = debug;
  REXLOG_INFO("PGR4 native frame generation: {}x{}{}{}", width, height, hdr ? " HDR10" : "",
              debug ? ", debug view" : "");
  return true;
}

void FrameGeneration::Prepare(uint64_t frame, CommandStream* list, const FfxApiResource& depth,
                              const FfxApiResource& motion, FfxApiDimensions2D render_size,
                              FfxApiFloatCoords2D jitter, FfxApiFloatCoords2D motion_scale,
                              const FfxCamera& camera, float frame_ms, bool reset) {
  if (!device_.has_swapchain() ||
      !Resize(device_.width(), device_.height(), device_.hdr(), FfxDebug()))
    return;
  ffxDispatchDescFrameGenerationPrepareV2 d = {};
  d.header.type = FFX_API_DISPATCH_DESC_TYPE_FRAMEGENERATION_PREPARE_V2;
  d.frameID = frame;
  d.renderSize = render_size;
  d.jitterOffset = jitter;
  d.motionVectorScale = motion_scale;
  d.frameTimeDelta = frame_ms;
  d.reset = reset;
  d.cameraNear = camera.near_plane;
  d.cameraFar = camera.far_plane;
  d.cameraFovAngleVertical = camera.fov_y;
  d.viewSpaceToMetersFactor = 1.0f;
  d.depth = depth;
  d.motionVectors = motion;
  // On the stream's thread, which records the list (as Generate's).
  list->Call([this, d](CommandStream::List* l) mutable {
    d.commandList = l;
    if (const ffxReturnCode_t rc = api_->dispatch(&context_, &d.header); rc != FFX_API_RETURN_OK)
      PGR4_WARN_ONCE("PGR4 native frame generation: prepare failed ({})", rc);
  });
  prepared_frame_ = frame;
}

ID3D12Resource* FrameGeneration::Generate(CommandStream* list, uint64_t frame, FfxApiRect2D rect,
                                          bool hudless) {
  ffxConfigureDescFrameGeneration c = {};
  c.header.type = FFX_API_CONFIGURE_DESC_TYPE_FRAMEGENERATION;
  c.frameGenerationEnabled = true;
  c.flags = FFX_FRAMEGENERATION_FLAG_NO_SWAPCHAIN_CONTEXT_NOTIFY;
  if (debug_) c.flags |= FFX_FRAMEGENERATION_FLAG_DRAW_DEBUG_VIEW;
  c.generationRect = rect;
  c.frameID = frame;
  if (hudless)
    c.HUDLessColor = ffxApiGetResourceDX12(hudless_.Get(), FFX_API_RESOURCE_STATE_PRESENT);
  ffxDispatchDescFrameGeneration d = {};
  d.header.type = FFX_API_DISPATCH_DESC_TYPE_FRAMEGENERATION;
  d.presentColor = ffxApiGetResourceDX12(image_.Get(), FFX_API_RESOURCE_STATE_PRESENT);
  d.outputs[0] = ffxApiGetResourceDX12(output_.Get(), FFX_API_RESOURCE_STATE_PRESENT);
  d.numGeneratedFrames = 1;
  d.backbufferTransferFunction =
      hdr_ ? FFX_API_BACKBUFFER_TRANSFER_FUNCTION_PQ : FFX_API_BACKBUFFER_TRANSFER_FUNCTION_SRGB;
  d.minMaxLuminance[1] = device_.hdr_peak_nits();
  d.generationRect = rect;
  d.frameID = frame;
  // On the stream's thread, which records the list: a failure leaves the output unwritten, and
  // shows from the next frame on.
  list->Call([this, c, d](CommandStream::List* l) mutable {
    d.commandList = l;
    ffxReturnCode_t rc = api_->configure(&context_, &c.header);
    if (rc == FFX_API_RETURN_OK) rc = api_->dispatch(&context_, &d.header);
    if (rc != FFX_API_RETURN_OK)
      PGR4_WARN_ONCE("PGR4 native frame generation: ffxDispatch failed ({})", rc);
  });
  return output_.Get();
}

}  // namespace pgr4::native
